"""PiSonde field GUI: presentation, cached network status, and offline help only."""
import json,socket,threading,time
from flask import jsonify,render_template_string
M=None
wifi_lock=threading.Lock();target_lock=threading.RLock()
wifi_state={'note':'checking'};target_cache={};loaded=False
PAGE='<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>PiSonde Mobile</title><style>\n:root{color-scheme:light}body{font:17px system-ui,sans-serif;margin:16px;max-width:900px;color:#18212b;background:#fff}h1{font-size:1.55rem;margin:0}h1 small{font-size:.85rem;font-weight:400;color:#536170}h2{font-size:1.2rem;margin:18px 0 10px}header{display:flex;align-items:center;gap:12px;flex-wrap:wrap}nav{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}a{color:#07579b;overflow-wrap:anywhere}nav a,button,select,input{font:inherit;min-height:44px;box-sizing:border-box;padding:10px;border:1px solid #a6b1bd;border-radius:5px;background:#fff}nav a{text-decoration:none;display:inline-flex;align-items:center}button{cursor:pointer;margin:5px 6px 5px 0;background:#eef2f6}button:disabled{opacity:.6}select{width:100%;margin:5px 0 10px}input{width:100%;margin:5px 0}label{display:block}#phase{font-size:1.15rem;font-weight:650;margin:16px 0 10px}.strip{display:flex;gap:7px;flex-wrap:wrap}.badge{padding:5px 8px;border-radius:4px;font-size:.85rem}.good{background:#e0f2e6;color:#174c2b}.warn{background:#fff0ce;color:#694b00}.neutral{background:#eef2f6;color:#394958}.error{color:#a21616;white-space:pre-wrap}small,.muted{font-size:.85rem;color:#536170;overflow-wrap:anywhere}#upload-status{font-size:.85rem;margin:10px 0}#summary{margin:8px 0;font-size:.9rem}.target{border:1px solid #cbd2da;border-radius:6px;padding:12px;margin:12px 0}.target article{padding:4px 0;overflow-wrap:anywhere}.target article b{display:block;font-size:1rem}.target a{display:inline-block;padding:6px 0}.target small{line-height:1.5}.earlier{border-top:1px solid #dce1e7;margin-top:10px;padding-top:10px}.earlier article{border-bottom:1px solid #e5e8ec;padding:10px 0}summary{cursor:pointer;min-height:32px;display:list-item;padding:4px 0}details p{margin:8px 0}#manual{padding:10px;background:#f5f7f9;border-radius:5px;margin:6px 0}#keep{border-color:#4f667c}button:focus-visible,a:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #1970bd;outline-offset:2px}\n</style></head><body><header><h1>PiSonde Mobile <small id="app-version">v{{version}}</small></h1><span id="live-status" class="badge neutral">Connecting</span></header>\n<nav aria-label="Main"><a href="/wifi">Wi-Fi</a><a href="/history">Recovery history</a><a href="/uploads">Uploads</a><a href="/updates">Updates</a><a href="/help">Help</a></nav>\n<p id="phase">Loading…</p><div class="strip"><span id="mode-status" class="badge neutral">Receiver</span><span id="radiohealth" class="badge neutral">SDR</span><span id="wifi-status" class="badge neutral">Uplink: checking</span></div><p id="upload-status">Checking upload status…</p><p id="error" class="error" role="status"></p>\n<label for="profile">Search mode</label><select id="profile">\n<option value="ALL">Auto — all modes</option><option value="APRS">APRS — 144.390 MHz</option>\n<option value="HORUS">Horus 432.501, 434.200, 434.210</option><option value="HORUS_WIDE">Horus — wide search 432–435 MHz</option><option value="DFM">DFM — search 400–406 MHz</option>\n<option value="RS41">RS41 — search 400–406 MHz</option><option value="MANUAL">Manual frequency</option><option value="STOP">Stop receiver</option></select>\n<div id="manual" hidden><label>Decoder<select id="decoder"><option>APRS</option><option>HORUS</option><option>DFM</option><option>RS41</option></select></label><label>Frequency (MHz)<select id="preset"></select><input id="custom" inputmode="decimal" aria-label="Custom frequency in MHz"></label><small>Custom frequency: enter MHz, then tap Done or leave the field.</small></div>\n<div><button id="resume">Resume scan</button><button id="keep">Lock to Frequency</button></div><p id="summary"></p>\n<h2>Latest positions / receptions</h2><div id="packets"></div>\n<details><summary>Receiver details</summary><p id="recovery"></p><p id="peaks"></p><p class="muted">Sample flow confirms streaming; a decoded packet confirms reception. Uplink shows the Wi-Fi association, not an Internet reachability test.</p><a href="/history.csv">Download complete CSV</a> · <a href="/sondehub-approval">Weather reception information</a></details>\n<script>\nconst token={{token|tojson}}, $=id=>document.getElementById(id);let initialized=false,busy=false,editing=false;\nconst presets={APRS:[\'144.390\'],HORUS:[\'432.501\',\'434.200\',\'434.210\'],DFM:[\'404.000\'],RS41:[\'404.000\']};\nfunction dms(value,latitude){let x=Math.round(Math.abs(value)*360000);const d=Math.floor(x/360000);x%=360000;const m=Math.floor(x/6000),s=(x%6000)/100;return `${d}° ${String(m).padStart(2,\'0\')}′ ${s.toFixed(2).padStart(5,\'0\')}″ ${latitude?(value>=0?\'N\':\'S\'):(value>=0?\'E\':\'W\')}`;}\nfunction fill(value){const list=presets[$(\'decoder\').value];$(\'preset\').replaceChildren(...list.map(v=>new Option(v+\' MHz\',v)),new Option(\'Custom…\',\'custom\'));const match=list.find(v=>Number(v)===Number(value));$(\'preset\').value=match||\'custom\';$(\'custom\').value=match||value;$(\'custom\').hidden=Boolean(match);}\nasync function send(values){if(busy)return;busy=true;try{const r=await fetch(\'/api/control\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\',\'X-CSRF-Token\':token},body:JSON.stringify(values)});if(!r.ok)throw Error(await r.text());$(\'error\').textContent=\'\';}catch(e){$(\'error\').textContent=e.message;}finally{busy=false;editing=false;}await refresh();}\nfunction select(){const value={profile:$(\'profile\').value};if(value.profile===\'MANUAL\'){value.manual_mode=$(\'decoder\').value;value.manual_mhz=Number($(\'custom\').value);if(!Number.isFinite(value.manual_mhz))return;}send(value);}\n$(\'profile\').onchange=()=>{$(\'manual\').hidden=$(\'profile\').value!==\'MANUAL\';select();};\n$(\'decoder\').onchange=()=>{fill(presets[$(\'decoder\').value][0]);select();};\n$(\'preset\').onchange=()=>{if($(\'preset\').value===\'custom\'){$(\'custom\').hidden=false;editing=true;$(\'custom\').focus();$(\'custom\').select();}else{$(\'custom\').hidden=true;$(\'custom\').value=$(\'preset\').value;select();}};\n$(\'custom\').onblur=()=>editing=false;$(\'custom\').onfocus=()=>editing=true;$(\'custom\').oninput=()=>editing=true;$(\'custom\').onchange=()=>select();$(\'custom\').onkeydown=e=>{if(e.key===\'Enter\'){$(\'custom\').blur();}};\n$(\'resume\').onclick=()=>send({action:\'resume\'});$(\'keep\').onclick=()=>send({action:\'keep\'});\nfunction copyCoordinates(text,button){const field=document.createElement(\'textarea\');field.value=text;document.body.append(field);field.select();field.setSelectionRange(0,text.length);const ok=document.execCommand(\'copy\');field.remove();button.textContent=ok?\'Copied\':\'Select coordinates to copy\';}\nfunction element(tag,text){const e=document.createElement(tag);e.textContent=text;return e;}\nfunction altitudeText(m){return m.toFixed(1)+\' m · \'+(m/0.3048).toFixed(1)+\' ft · \'+(m/1609.344).toFixed(2)+\' mi\';}\nfunction createPacketNode(p){const a=element(\'article\',\'\');a.append(element(\'b\',p.callsign+\' · \'+p.protocol+\' · \'+p.frequency_mhz.toFixed(6)+\' MHz\'),element(\'br\',\'\'),ageLabel(p.received_utc),element(\'br\',\'\'));\nif(p.latitude!==null&&p.longitude!==null){const link=element(\'a\',p.latitude.toFixed(6)+\', \'+p.longitude.toFixed(6));link.href=\'https://www.google.com/maps/search/?api=1&query=\'+encodeURIComponent(p.latitude+\',\'+p.longitude);link.target=\'_blank\';link.rel=\'noopener\';a.append(link,element(\'br\',\'\'));const d=element(\'a\',dms(p.latitude,true)+\', \'+dms(p.longitude,false));d.href=link.href;d.target=\'_blank\';d.rel=\'noopener\';const copy=element(\'button\',\'Copy coordinates\');copy.onclick=()=>copyCoordinates(p.latitude.toFixed(6)+\', \'+p.longitude.toFixed(6),copy);a.append(d,element(\'br\',\'\'),copy,element(\'br\',\'\'));if(p.altitude_m!==null)a.append(element(\'small\',\'Altitude reported by packet: \'+altitudeText(p.altitude_m)),element(\'br\',\'\'));}\nconst details=document.createElement(\'details\');details.append(element(\'summary\',\'Packet\'),element(\'small\',p.raw_packet));a.append(details);return a;}\nfunction age(value){const seconds=Math.max(0,Math.floor((Date.now()-new Date(value).getTime())/1000));if(!Number.isFinite(seconds))return \'time unavailable\';if(seconds<60)return seconds+\'s ago\';if(seconds<3600)return Math.floor(seconds/60)+\'m ago\';if(seconds<86400)return Math.floor(seconds/3600)+\'h ago\';return Math.floor(seconds/86400)+\'d ago\';}\nfunction ageLabel(value){const e=element(\'small\',\'Last received \'+age(value));e.dataset.age=value;e.title=value+\' (stored reception time)\';return e;}\nconst packetNodes=new Map(),targetCards=new Map();\nfunction packetNode(p){const key=String(p.id);if(!packetNodes.has(key))packetNodes.set(key,createPacketNode(p));return packetNodes.get(key);}\nfunction reconcile(host,nodes){for(let i=0;i<nodes.length;i++){if(host.children[i]!==nodes[i])host.insertBefore(nodes[i],host.children[i]||null);}for(const node of Array.from(host.children))if(!nodes.includes(node))node.remove();}\nfunction renderPackets(rows){\n const host=$(\'packets\'),cards=[];\n for(const p of rows){\n  const key=p.protocol+\'|\'+p.callsign;let card=targetCards.get(key);\n  if(!card){const root=element(\'section\',\'\'),latest=element(\'div\',\'\'),history=element(\'details\',\'\'),summary=element(\'summary\',\'Earlier receptions\'),older=element(\'div\',\'\');root.className=\'target\';history.className=\'earlier\';history.append(summary,older);root.append(latest,history);card={root,latest,history,summary,older};targetCards.set(key,card);}\n  const node=packetNode(p),prior=card.latest.children[0],previous=(p.earlier||[]).map(packetNode);\n  if(prior&&prior!==node&&prior.querySelector(\'details\').open){if(!previous.includes(prior))previous.unshift(prior);card.history.open=true;}\n  for(const n of Array.from(card.older.children))if(n!==node&&n.querySelector(\'details\').open&&!previous.includes(n))previous.push(n);\n  reconcile(card.latest,[node]);reconcile(card.older,previous);\n  card.summary.textContent=\'Earlier receptions (\'+previous.length+\' shown)\';card.history.hidden=!previous.length;cards.push(card.root);\n }\n for(const [key,card] of targetCards){if(!cards.includes(card.root)){if(Array.from(card.root.querySelectorAll(\'details\')).some(n=>n.open))cards.push(card.root);else{card.root.remove();targetCards.delete(key);}}}\n if(!cards.length){const empty=element(\'p\',\'Waiting for packets.\');reconcile(host,[empty]);}else reconcile(host,cards);\n for(const [id,node] of packetNodes)if(!node.isConnected)packetNodes.delete(id);\n for(const e of host.querySelectorAll(\'[data-age]\'))e.textContent=\'Last received \'+age(e.dataset.age);\n}\nlet lastStatusAt=0;\nfunction updateTop(s){\n lastStatusAt=Date.now();const mode=s.config.profile===\'STOP\'?\'Stopped\':s.config.profile===\'MANUAL\'?\'Locked\':s.hold_remaining?\'Tracking\':\'Scanning\';$(\'mode-status\').textContent=mode;$(\'mode-status\').className=\'badge \'+(mode===\'Stopped\'?\'warn\':\'good\');\n $(\'radiohealth\').textContent=\'SDR: \'+s.sdr_state;$(\'radiohealth\').className=\'badge \'+(s.sdr_state===\'Samples flowing\'?\'good\':\'neutral\');\n $(\'recovery\').textContent=\'Recoveries: \'+s.sdr_restarts+\' · USB resets: \'+s.sdr_usb_resets+(s.sdr_last_fault?\' · Last fault: \'+s.sdr_last_fault:\'\');\n const w=s.ui_wifi||{},wh=w.recovery||{};$(\'recovery\').textContent+=\' · Wi-Fi adapter attempts: \'+(wh.adapter_attempts||0)+\' · Shared Wi-Fi service attempts: \'+(wh.service_attempts||0)+(wh.last_reason?\' · \'+wh.last_reason:\'\');$(\'wifi-status\').textContent=\'Uplink: \'+(w.hotspot||w.note||\'offline\');$(\'wifi-status\').className=\'badge \'+(w.hotspot?\'good\':\'warn\');\n const u=s.upload||{},d=u.destinations||{},count=(dest,key)=>((d[dest]||{}).counts||{})[key]||0;\n const weather=\'local only\';\n $(\'upload-status\').textContent=(u.settings&&u.settings.enabled===false?\'Uploads paused · \':\'\')+\'APRS sent \'+count(\'aprs\',\'sent\')+\' · Horus accepted \'+count(\'amateur\',\'accepted\')+\' · Weather: \'+weather+\' · Queued \'+((u.counts||{}).pending||0);\n $(\'summary\').textContent=s.packets+\' stored packets · \'+s.free_gib+\' GiB free\'+(s.storage_warning?\' · \'+s.storage_warning:\'\');\n $(\'live-status\').textContent=\'Live\';$(\'live-status\').className=\'badge neutral\';\n}\nsetInterval(()=>{if(lastStatusAt&&Date.now()-lastStatusAt>10000){$(\'live-status\').textContent=\'Status stale\';$(\'live-status\').className=\'badge warn\';}},2000);\nasync function refresh(){try{const r=await fetch(\'/api/status\',{cache:\'no-store\'});if(!r.ok)throw Error(\'Status unavailable\');const s=await r.json();\n$(\'phase\').textContent=s.phase+(s.mode?\' — \'+s.mode:\'\')+(s.frequency_mhz?\' · \'+s.frequency_mhz.toFixed(6)+\' MHz\':\'\')+(s.hold_remaining?\' · \'+s.hold_remaining+\'s hold\':\'\');\n$(\'radiohealth\').textContent=\'SDR: \'+s.sdr_state+\' · recovery attempts: \'+s.sdr_restarts+\' · USB resets: \'+s.sdr_usb_resets;\nif(!busy)$(\'error\').textContent=s.error;$(\'summary\').textContent=s.packets+\' stored packets · \'+s.free_gib+\' GiB free\';\nif(!busy){$(\'profile\').value=s.config.profile;$(\'manual\').hidden=s.config.profile!==\'MANUAL\';if(!editing){$(\'decoder\').value=s.config.manual_mode;fill(s.config.manual_mhz);}initialized=true;}\n$(\'peaks\').textContent=s.candidates.length?s.candidates.map(p=>p.frequency_mhz.toFixed(6)+\' MHz (\'+p.above_floor_db+\' dB above local floor)\').join(\' · \'):\'No candidate peaks in the latest sweep.\';\nupdateTop(s);renderPackets(s.ui_targets||s.recent);\n}catch(e){$(\'error\').textContent=e.message;}}\nrefresh();setInterval(refresh,2000);\n</script></body></html>'

def wifi_poll():
    while not M.shutdown_event.is_set():
        try:
            with socket.socket(socket.AF_UNIX,socket.SOCK_STREAM) as sock:
                sock.settimeout(4);sock.connect('/run/pisonde-control/control.sock');sock.sendall(b'{"action":"status"}\n')
                with sock.makefile('rb') as f:reply=json.loads(f.readline(100000))
            if not reply.get('ok'):raise RuntimeError('Network status unavailable')
            result=dict(reply['result'],checked_at=time.monotonic())
        except Exception:result={'note':'status unavailable','checked_at':time.monotonic()}
        with wifi_lock:wifi_state.clear();wifi_state.update(result)
        if M.shutdown_event.wait(15):break

def latest_targets(recent):
    global loaded
    with target_lock:
        with M.database() as db:
            rows=list(reversed(recent))
            if not loaded:
                ids=[r[0] for r in db.execute('SELECT MAX(id) FROM receptions GROUP BY callsign,protocol ORDER BY MAX(id) DESC LIMIT 30')]
                rows=([dict(r) for r in db.execute('SELECT * FROM receptions WHERE id IN ('+','.join('?' for _ in ids)+') ORDER BY id',ids)] if ids else [])+rows
                loaded=True
            for last in rows:
                key=(last['protocol'],last['callsign']);entry=target_cache.get(key)
                if entry and entry['last_id']>=last['id']:continue
                if last['latitude'] is not None and last['longitude'] is not None:position=last
                else:
                    found=db.execute('SELECT * FROM receptions WHERE callsign=? AND protocol=? AND latitude IS NOT NULL AND longitude IS NOT NULL ORDER BY id DESC LIMIT 1',(last['callsign'],last['protocol'])).fetchone()
                    position=dict(found) if found else last
                earlier=[dict(r) for r in db.execute('SELECT * FROM receptions WHERE callsign=? AND protocol=? AND id<? ORDER BY id DESC LIMIT 10',(last['callsign'],last['protocol'],position['id']))]
                target_cache[key]=dict(position,last_id=last['id'],last_packet_received_utc=last['received_utc'],earlier=earlier)
            ordered=sorted(target_cache.items(),key=lambda item:item[1]['last_id'],reverse=True)[:30]
            target_cache.clear();target_cache.update(ordered)
            return [dict(v) for _,v in ordered]

HELP="""<h2>PiSonde Mobile field guide</h2><p>Connect your phone to <strong>pisondemobile</strong> and open <a href="http://192.168.73.1">192.168.73.1</a>. No Internet is needed to view stored receptions.</p>
<h3>Receiving</h3><p>Choose a search mode to start scanning. Auto—all modes cycles APRS, the three configured Horus launch channels, and weather-sonde discovery. Horus wide search is a separate option for 432–435 MHz. One SDR can receive only one tuned channel at a time.</p><p>A valid decoded packet starts or renews the automatic 65-second hold. Lock to Frequency holds the current decoder and frequency indefinitely. Resume scan releases the lock. Manual frequency allows APRS, Horus, DFM, or RS41 at a frequency you enter.</p><p>At service startup, a saved manual lock or stopped state returns to Auto—all modes. Other selected scanning profiles are preserved. Stop receiver pauses this running session.</p>
<h3>Finding a payload</h3><p>Each card shows the latest stored position for that callsign and protocol, or its latest reception when no position is available. “Last received” is the age of that displayed record, based on your browser clock. Old positions remain useful for recovery but are not current live positions.</p><p>Tap either coordinate format for Google Maps. Decimal coordinates and degrees/minutes/seconds are both shown. Copy coordinates provides plain decimal coordinates. Altitude is shown as reported by the packet, without assuming an altitude datum.</p><p>Earlier receptions shows up to ten older records. An expanded packet remains available while you read it. Use Recovery history for complete CSV/GPX exports and recovery notes.</p>
<h3>Wi-Fi and uploads</h3><p>Onboard Wi-Fi serves pisondemobile; the Linksys USB adapter connects to Internet hotspots. The Uplink badge reports the saved connection name, not a connectivity test. Removing the Linksys should leave the local AP available after the role update.</p><p>APRS packets are forwarded to APRS-IS; its “sent” count means a socket write, not confirmation that aprs.fi stored a packet. Horus uses SondeHub Amateur. DFM and RS41 are decoded and stored locally; PiSonde Mobile does not upload weather telemetry to sondehub.org. <a href="/sondehub-approval">Weather reception information</a>.</p><p>Local history is retained when uploads fail. Old upload jobs expire to avoid presenting stale data as live telemetry. Exports preserve original packet times and never retransmit old data.</p>
<h3>Storage and retention</h3><p>Uploads contains the retention controls. Keep forever is the default. Optional day limits are 30, 60, 90, 180 or 365 days; low-space mode defaults to a 10% free-space trigger. Enabling cleanup requires confirmation. Location protection preserves each target’s latest position and the latest reception for noted/recovery-marked targets. The newest reception is always kept, and low-space mode keeps the newest five minutes. Cleanup removes eligible receptions and linked upload/validation payloads; notes, backups and diagnostic logs have separate retention. Export important CSV/GPX/validation data first. Checks run at startup, about every five minutes and after saving. SQLite compaction needs temporary space and may be deferred; cleanup cannot remove unrelated files.</p><h3>Wi-Fi recovery</h3><p>The root broker monitors repeated upstream control timeouts and onboard authentication errors independently of reception. Wi-Fi shows recovery counters. Recovery may briefly disconnect clients; it is rate limited and deferred during update/power operations. Missing coverage and an idle AP are not faults. No automatic Pi reboot. Counters reset when the broker restarts. Underlying hardware/driver faults and intermittent SDR stalls remain under investigation.</p><h3>Health and power</h3><p>Samples flowing means sample bytes are moving through the pipeline, not that a radio signal decoded. Receiver details contains cumulative recovery/reset counters for the running service. Service restarts reset those counters.</p><p>The watchdog restarts stalled pipelines and can perform a bounded, targeted RTL-SDR USB reset. Device controls offers an optional reboot after USB reset recovery is exhausted, limited to one per hour and deferred during updates. It is disabled by default. The underlying intermittent stall has not been conclusively diagnosed.</p><p>Use <a href="/device">Device controls</a> → Shut down Pi, or the installed shutdown button, before removing power when possible. Database durability settings and checked backups reduce risk; they do not guarantee protection against arbitrary power loss.</p>"""
APPROVAL="""<h2>Weather reception: local only</h2><p>PiSonde Mobile decodes DFM and RS41 telemetry for local chasing, coordinate display, history and CSV/GPX export. Direct weather uploads to sondehub.org were removed in 0.3.19. Old pending weather upload jobs are disabled without removing reception history.</p><p>APRS-IS and Horus uploads to SondeHub Amateur remain separate supported paths. The development endpoint test contacts only SondeHub Amateur.</p><p>For weather uploads, use established software such as <a href="https://github.com/projecthorus/radiosonde_auto_rx">radiosonde_auto_rx</a>. Integration of its UDP telemetry into this dashboard is not implemented.</p><p><a href="/history">Recovery history</a> · <a href="/history.csv">CSV export</a> · <a href="/track.gpx">GPX export</a>. Historical JSONL payload exports on Uploads contain only records saved by older versions; they do not generate or resend weather uploads.</p>"""

def install(module,start_threads=True):
    global M,loaded
    M=module;loaded=False;target_cache.clear()
    import field_features as features
    M.PAGE=PAGE.replace('</style>',features.THEME+'</style>')
    M.PAGE=M.PAGE.replace('<a href="/updates">Updates</a>', '<a href="/updates">Updates</a><a href="/device">Device controls</a>')
    M.PAGE=M.PAGE.replace('<nav aria-label="Main">','<nav aria-label="Main"><a href="/" aria-current="page">Receiver</a>')
    def retention_changed():
        global loaded
        with target_lock:loaded=False;target_cache.clear()
    M.retention_changed=retention_changed
    M.PAGE=M.PAGE.replace('let lastStatusAt=0;', 'let lastStatusAt=0,lastRetentionGeneration=null;')
    M.PAGE=M.PAGE.replace('updateTop(s);renderPackets(s.ui_targets||s.recent);', "if(lastRetentionGeneration!==null&&lastRetentionGeneration!==s.retention_generation){packetNodes.clear();targetCards.clear();$('packets').replaceChildren();}lastRetentionGeneration=s.retention_generation;updateTop(s);renderPackets(s.ui_targets||s.recent);")
    import update_ui
    update_ui.install(M)
    import field_features as features
    previous=M.app.view_functions['api_status']
    def status():
        data=previous().get_json()
        data['ui_targets']=latest_targets(data['recent'])
        with wifi_lock:data['ui_wifi']=dict(wifi_state)
        if data['ui_wifi'].get('checked_at') and time.monotonic()-data['ui_wifi']['checked_at']>45:data['ui_wifi']={'note':'status unavailable'}
        data['ui_weather_local_only']=True
        response=jsonify(data);response.headers['Cache-Control']='no-store';return response
    M.app.view_functions['api_status']=status
    M.app.add_url_rule('/help','field_ui_help',lambda:features.page(HELP))
    M.app.add_url_rule('/sondehub-approval','field_ui_approval',lambda:features.page(APPROVAL))
    if start_threads:threading.Thread(target=wifi_poll,name='ui-wifi-status',daemon=True).start()
